--
-- Table structure for table `tenant_payments`
--

CREATE TABLE `tenant_payments` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `renting_id` bigint(20) UNSIGNED DEFAULT NULL,
  `tenant_id` bigint(20) UNSIGNED NOT NULL,
  `months` int(11) DEFAULT NULL,
  `amount` int(11) NOT NULL,
  `balance` int(11) NOT NULL,
  `details` text DEFAULT NULL,
  `commission_type` varchar(255) DEFAULT NULL,
  `commission_type_value` int(11) DEFAULT NULL,
  `commission_amount` int(11) DEFAULT NULL,
  `landlord_amount` int(11) DEFAULT NULL,
  `payment_method` text DEFAULT NULL,
  `payment_destination` text DEFAULT NULL,
  `transaction_number` text DEFAULT NULL,
  `account_number` text DEFAULT NULL,
  `house_id` int(11) DEFAULT NULL,
  `room_id` int(11) DEFAULT NULL,
  `landload_id` int(11) DEFAULT NULL,
  `securty_deposit` bigint(20) DEFAULT 0,
  `days_before` bigint(20) DEFAULT 0,
  `garbage_amount` decimal(10,2) DEFAULT NULL,
  `rent_amount` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

